async function save(next:Data,event:string){if(saving.current)return false;saving.current=true;setBusy(true);setError('');const data={...next,events:[{id:id(),text:event,date:new Date().toISOString()},...next.events].slice(0,250)};try{if(persist){if(cloud?.role==='viewer')throw Error('Your account has read-only access. Ask a firm administrator for editing access.');if(!await persist(data,event))throw Error('Cloud save was not confirmed. Resolve the save error before continuing.');}else localStorage.setItem('kalling-pages-demo-v1',JSON.stringify(data));unsaved.current=null;setW(data);return true;}catch(e){unsaved.current=data;setError(persist?(e instanceof Error?e.message:'Cloud save failed. Your changes were not saved.'): 'Browser storage is full or unavailable. Export your workspace and remove large documents.');return false;}finally{saving.current=false;setBusy(false);}}
