function openDesk(link:DeskLink){go(link.page,link.focus||{});if(link.page==='Screening'&&link.focus?.companyId)setScreenId(link.focus.companyId);if(link.companyTab&&link.focus?.companyId){const company=w!.companies.find(c=>c.id===link.focus!.companyId);if(company){open(company);setTab(link.companyTab);}}}
