async function importCSV(file:File){try{if(file.size>2e6)throw Error('CSV limit is 2 MB.');const rows=parseCSV(await file.text()),head=rows.shift()?.map(s=>s.toLowerCase().replace(/[ -]/g,'_'))||[];if(!head.includes('name')||!head.includes('state'))throw Error('CSV requires name and state columns.');if(rows.length>500)throw Error('Import up to 500 rows at a time.');const keys=new Set(w!.companies.map(x=>[x.name,x.city,x.state].join('|').toLowerCase())),added:Company[]=[];let skipped=0;for(const row of rows){const get=(key:string)=>row[head.indexOf(key)]||'',name=get('name'),city=get('city'),state=get('state').toUpperCase(),key=[name,city,state].join('|').toLowerCase();if(!name||!states.includes(state)||keys.has(key)){skipped++;continue;}keys.add(key);added.push({id:id(),name,city,state,industry:get('industry')||'Locksmith',website:safeURL(get('website')),owner:get('owner'),email:get('email'),phone:get('phone'),sample:false,status:'New',nextAction:'Research company and verify ownership',due:nextDate(),assignedTo:responsibleFor(w!,'Research dossier'),evidence:[],documents:[],conversations:[],drafts:[]});}if(!added.length)throw Error('No new US companies found. Check states and duplicates.');if(await save(attachPrimarySearch({...w!,companies:[...added,...w!.companies]},added.map(c=>c.id)),`Imported ${added.length} companies; skipped ${skipped} rows.`)){close();go('Companies');setToast(`${added.length} companies imported. ${skipped} rows skipped.`);}}catch(e){setError(e instanceof Error?e.message:'Import failed.');}}
