function exportCSV(){const quote=(s:string)=>'"'+(/^[=+@\-]/.test(s)?"'"+s:s).replaceAll('"','""')+'"';download('kalling-companies.csv',[['name','city','state','industry','website','owner','email','phone','sample'].join(','),...visible.map(x=>[x.name,x.city,x.state,x.industry,x.website,x.owner,x.email,x.phone,String(x.sample)].map(quote).join(','))].join('\n'),'text/csv');}
function Table({items=visible}:{items?:Company[]}){return <div className="table-scroll"><table><thead><tr>{['Company','Location','Stage','Research','Next action','Due',''].map((x,i)=><th key={i}>{x}</th>)}</tr></thead><tbody>{items.map(x=>{const sources=new Set([...x.evidence,...x.documents.flatMap(d=>d.evidence)].map(e=>e.source)).size;return <tr key={x.id} onClick={()=>open(x)}><td><button className="company-cell" onClick={()=>open(x)}><span className={'avatar a'+x.name.length%4}>{x.name.split(' ').slice(0,2).map(s=>s[0]).join('')}</span><span><strong>{x.name}</strong><small>{x.industry}{x.sample?' · Sample':''}</small></span></button></td><td className="location-cell">{x.city}<small>{x.state}</small></td><td className="stage-cell"><Badge tone={x.status==='Interested'?'green':x.status==='Contacted'?'blue':'neutral'}>{x.status}</Badge></td><td className="research-cell"><span className="source-count"><i className={'dot '+(sources?'green':'')}/>{sources?`${sources} source${sources===1?'':'s'}`:'Needs research'}</span></td><td className="next-cell">{x.nextAction||'Set next action'}</td><td className={'date-cell '+(x.due<=today()?'due':'')}>{dateLabel(x.due)}</td><td className="row-arrow"><ChevronRight size={15}/></td></tr>;})}</tbody></table>{!items.length&&<div className="empty"><Search/><h3>No companies here yet</h3><p>Add a company or import a target list.</p><button className="btn primary" onClick={()=>setModal('add')}>Add company</button></div>}</div>;}
function ScreenPanel({company}:{company:Company}){const s=screen(company,effectiveFirm(w!,company));return <><ReviewStandards w={w!} company={company}/><div className="screen-grid"><div><DocumentInputs company={company} busy={busy} onSave={async(doc,replacingId)=>{const changed=addDocument(company,doc,replacingId),next={...w!,companies:w!.companies.map(c=>c.id===changed.id?changed:c)},brief=prepareInvestmentBrief(next,changed);return save({...next,operating:{...ops(next),briefs:[brief,...ops(next).briefs]}},`Saved ${doc.name} and prepared investment brief v${brief.version} for ${company.name}.`);}}/><section className="panel"><div className="section-head"><h3>Financial observations</h3></div>{s.evidence.filter(e=>/^(revenue|ebitda|sde|adjusted_ebitda)/.test(e.field)).map(e=><div className="observation" key={e.id}><div><strong>{e.field.toUpperCase().replaceAll('_',' ')} <Badge tone={e.kind==='reported'&&!e.disputed?'blue':'orange'}>{e.disputed?'Disputed':e.basis||e.kind}</Badge></strong><b>{money(number(e.value))}</b></div><blockquote>{e.excerpt}</blockquote><small>{e.source}{e.locator?' · '+e.locator:''}</small></div>)}</section></div><section className="panel"><div className="section-head"><h2>Initial screen</h2><Badge tone={s.status==='Ready for review'?'green':'orange'}>{s.status}</Badge></div><div className="padded"><h3>{company.name}</h3><p>Against {effectiveFirm(w!,company).name}'s current buy box</p></div>{s.checks.map(check=><div className="check-row" key={check.label}><span className={'check-icon '+check.result}>{check.result==='pass'?<Check size={14}/>:check.result==='fail'?<X size={14}/>:<CircleHelp size={14}/>}</span><div><strong>{check.label}<Badge tone={check.result==='pass'?'green':check.result==='conflict'?'orange':'neutral'}>{check.result}</Badge></strong><p>{check.detail}</p></div></div>)}<div className="screen-actions"><button className="btn primary full" onClick={()=>{if(!c)open(company);setTab('Investment brief');}}>Review investment brief <ArrowRight size={15}/></button><button className="btn full" onClick={()=>read(memo(company,effectiveFirm(w!,company)),'memo')}><FileText size={15}/>Prepare screening summary</button><button className="btn primary full" disabled={busy||w!.deals.some(d=>d.companyId===company.id)} onClick={()=>{setScreenId(company.id);setModal('promote');}}>{w!.deals.some(d=>d.companyId===company.id)?'Opportunity already opened':'Review & open opportunity'}<ArrowRight size={15}/></button><small>Human review required. Unresolved issues remain visible.</small></div></section></div></>;}
